package bons.furious.mixin.mcreator_pv_c49;

import org.spongepowered.asm.mixin.Mixin;

/**
 * mcreator_shared_default_player_variables (since 1.0.49): carrier for Luminous Beasts 100K V1.2.3 - Forge 1.20.1.jar (common classes; generated by
 * tools/mixedproof/McreatorPvC49Census.py --write from the build census: 12 classes, 12 accepted read sites of
 * net.mcreator.luminousbeasts.network.LuminousBeastsModVariables$PlayerVariables). The mixin itself is empty: before it is applied to a class, the group's plugin
 * (bons.furious.patch.mcreator_pv_c49.SharedDefaultsPlugin) re-checks every site of that class and rewrites only the accepted
 * ones (bons.furious.patch.mcreator_pv_c49.PvRewrite). Our own logic only; the mod's code stays in its jar.
 */
@Mixin(targets = {
        "net.mcreator.luminousbeasts.procedures.CoalDropProcedure",
        "net.mcreator.luminousbeasts.procedures.CowlDropProcedure",
        "net.mcreator.luminousbeasts.procedures.FeatherDropProcedure",
        "net.mcreator.luminousbeasts.procedures.GatorToothDropProcedure",
        "net.mcreator.luminousbeasts.procedures.PouchDropProcedure",
        "net.mcreator.luminousbeasts.procedures.PumpkinHelmetDropProcedure",
        "net.mcreator.luminousbeasts.procedures.RattleDropProcedure",
        "net.mcreator.luminousbeasts.procedures.RootDropProcedure",
        "net.mcreator.luminousbeasts.procedures.ShelldropProcedure",
        "net.mcreator.luminousbeasts.procedures.ViperToothDropProcedure",
        "net.mcreator.luminousbeasts.procedures.WrapsdropProcedure",
        "net.mcreator.luminousbeasts.procedures.YetiHornDropProcedure"
}, remap = false)
public abstract class LuminousBeastsPvCarrier {
}
